function sRGB (v)
if (v <= 0.04045) then v = v / 12.92 else v = math.pow((v+0.055)/1.055, 2.4) end return v end
function rgb2lum(R, G, B)
return 0.2126 * sRGB(R/255) + 0.7152 * sRGB(G/255) + 0.0722 * sRGB(B/255) end
function checker(arg)
if colourname[arg:lower()] == nil then
if string.sub(arg,1,1) == '#' and tonumber(string.sub(arg,2,7),16) ~= nil and ( #arg == 7 or 4 ) then return arg else error(arg .. ' is not a valid colour') end else return arg end end
function colour2lum(c)
if checker(c) then
if (colourname[c:lower()] ~= nil) then return colourname[c:lower()] end
if( #c == 7 ) then local R = tonumber(string.sub(c,2,3),16) local G = tonumber(string.sub(c,4,5),16) local B = tonumber(string.sub(c,6,7),16) return rgb2lum(R, G, B) else local R = 16*tonumber(string.sub(c,2,2),16) + tonumber(string.sub(c,2,2),16) local G = 16*tonumber(string.sub(c,3,3),16) + tonumber(string.sub(c,3,3),16) local B = 16*tonumber(string.sub(c,4,4),16) + tonumber(string.sub(c,4,4),16) return rgb2lum(R, G, B) end end end
function p.contraster(bg,c)
if bg == nil then
if colour2lum(c) < 0.2126 then return '[[Category:Colour bad on dark mode]]'
elseif colour2lum(c) > 0.2126 and colour2lum(c) < 0.4 then return ''
elseif colour2lum(c) > 0.4 then return '[[Category:Colour bad on light mode]]'
end elseif bg ~= nil then
return '' end end function p.mes(frame) local title = mw.title.getCurrentTitle() local args = frame:getParent().args local bg = args.bg local c = args.colour or args.color or 'white' if c == 'white' then return '' elseif title.namespace == 0 or title.namespace == 120 then return p.contraster(bg,c) end end function p.overhead(frame) local title = mw.title.getCurrentTitle() local args = frame:getParent().args local bg = args.bg local c = args.colour or args.color or 'yellow' if c == 'yellow' then return '' elseif title.namespace == 0 or title.namespace == 120 then return p.contraster(bg,c) end end function p.colour(frame) local title = mw.title.getCurrentTitle() local args = frame:getParent().args local bg = args[3] local c = args[1] if title.namespace == 0 or title.namespace == 120 then return p.contraster(bg,c) end end return p

--------------------------
-- Module for [[Template:Infobox Item]]
------------------------
local p = {}

local infobox = require('Module:Infobox')
local onmain = require('Module:Mainonly').on_main
local commas = require('Module:Addcommas')._add
local exchange = require('Module:Exchange')
local chart = require('Module:ExchangeData')._chart
local tb = require('Module:Trailblazer Region')
local yesNo = require('Module:Yesno')

function p.main(frame)
	local args = frame:getParent().args
	local ret = infobox.new(args)
	local default_version_index = tonumber(args.defver) or 1

	ret:defineParams{
		{ name = 'name', func = 'name' },
		{ name = 'name_bucket', func = { name = name_bucket, params = { 'name' }, flag = 'p' } },
		{ name = 'version', func = 'has_content' },
		{ name = 'default_version', func = { name = is_default_version, params = { args['bucketname' .. default_version_index] or '', args['version' .. default_version_index] or '', 'bucketname', 'version' }, flag = { 'r', 'r', 'd', 'd' } } },
		{ name = 'aka', func = 'has_content' },
		{ name = 'image', func = 'image' },
		{ name = 'image_bucket', func = { name = image_bucket, params = { 'image' }, flag = 'p' } },

		{ name = 'release', func = 'release' },
		{ name = 'removal', func = 'removal' },
		{ name = 'members', func = 'has_content' },
		{ name = 'members_bucket', func = { name = yesNo, params = { 'members' } } },
		{ name = 'quest', func = 'has_content' },
		{ name = 'leagueRegion', func = tb.regionsForInfobox },
		{ name = 'leagueRegion_raw', func = { name = 'has_content', params = { 'leagueRegion' }, flag = 'p' } },

		{ name = 'tradeable', func = tradeablearg },
		{ name = 'tradeable_bucket', func = { name = yesNo, params = { 'tradeable' } } },
		{ name = 'bankable', func = 'has_content' },
		{ name = 'stacksinbank', func = 'has_content' },
		{ name = 'equipable', func = 'has_content' },
		{ name = 'stackable', func = 'has_content' },
		{ name = 'noteable', func = 'has_content' },
		{ name = 'edible', func = 'has_content' },
		{ name = 'options', func = 'has_content' },
		{ name = 'wornoptions', func = wornoptionsarg },
		{ name = 'destroy', func = 'has_content' },
		{ name = 'examine', func = 'has_content' },

		{ name = 'raw_value', func = { name = valraw, params = { 'value' }, flag = 'p' } },
		{ name = 'value', func = { name = valuearg, params = { 'raw_value' } } },

		{ name = 'alchable', func = { name = alchablearg, params = { 'alchable' }, flag = 'p' } },
		{ name = 'high', func = { name = alchvalues, params = { 'raw_value', 0.6, 'alchable' }, flag = { 'd', 'r', 'd' } } },
		{ name = 'low', func = { name = alchvalues, params = { 'raw_value', 0.4, 'alchable' }, flag = { 'd', 'r', 'd' } } },
		{ name = 'high_bucket', func = { name = alchvalues_bucket, params = { 'raw_value', 0.6, 'alchable' }, flag = { 'd', 'r', 'd' } } },

		{ name = 'raw_weight', func = { name = weight_raw, params = { 'weight' }, flag = 'p' } },
		{ name = 'weight', func = weightarg },
		{ name = 'respawn', func = respawnarg },

		{ name = 'gemw', func = { name = gemwarg, params = { 'exchange' }, flag = 'p' } },
		{ name = 'gemwname', func = { name = gemwnamearg, params = { 'name', 'gemwname' } } },
		{ name = 'gemwprice', func = { name = gemwpricearg, params = { 'gemw', 'gemwname' } } },
		{ name = 'exchange', func = { name = exchangearg, params = { 'gemwprice', 'gemwname' } } },
		-- dupes = true allows the css class to hide rows on undefined verisions
		-- css class name to hide rows on undefined versions
		{ name = 'gemwdisp', func = { name = gemwdisparg, params = { 'gemw' } }, dupes = true },
		{ name = 'buylimit', func = { name = buylimitarg, params = { 'gemwprice', 'gemwname' } }, dupes = true },
		{ name = 'buylimit_bucket', func = { name = buylimit_bucket, params = { 'buylimit' } } },
		{ name = 'volume', func = { name = volumearg, params = { 'gemwprice', 'gemwname' } }, dupes = true },
		{ name = 'realtime', func = { name = realtimearg, params = { 'gemwprice', 'gemwname' } }, dupes = true},
		{ name = 'realtimedmm', func = { name = realtimedmmarg, params = { 'gemwname', 'gemw' } } },
		{ name = 'graph', func = { name = gemwgrapharg, params = { 'gemwprice', 'gemwname' } } },

		{ name = 'dropversion', func = 'has_content' },
        { name = 'usesinfobox', func = { name = tostring, params = { 'Item' }, flag = 'r' } },
		{ name = 'id', func = 'has_content' },
		{ name = 'id_bucket', func = { name = id_bucket, params = { 'id' }, flag = 'p' } },
		{ name = 'chisel_link', func = { name = 'chisel_link', params = { 'id', 'name', 'item' }, flag = { 'p', 'p', 'r' } } },
	}

	ret:setMaxButtons(10)
	ret:create()
	ret:cleanParams()
	ret:customButtonPlacement(true)

	-- adds the classname in 'gemwdisp' to the rows containing 'buylimit' and 'volume'
	ret:linkParams{
